blocks.bootstrap:
let didStartBuffer = false;
process.nextTick(() => {
    if (creds.me?.id) {
        // start buffering important events
        // if we're logged in
        ev.buffer();
        didStartBuffer = true;
        config.optimusInitialBufferRecovery?.start({ ev, ws });
    }
    ev.emit('connection.update', { connection: 'connecting', receivedPendingNotifications: false, qr: undefined });
});
// called when all offline notifs are handled
ws.on('CB:ib,,offline', (node) => {
    const child = getBinaryNodeChild(node, 'offline');
    const offlineNotifs = +(child?.attrs.count || 0);
    logger.info(`handled ${offlineNotifs} offline messages/notifications`);
    config.optimusInitialBufferRecovery?.complete();
    if (didStartBuffer) {
        ev.flush();
        logger.trace('flushed events for initial buffer');
    }
    ev.emit('connection.update', { receivedPendingNotifications: true });
});

blocks.upsert:
const upsertMessage = ev.createBufferedFunction(async (msg, type) => {
    config.optimusInitialBufferRecovery?.observeMessage(msg, type);
    ev.emit('messages.upsert', { messages: [msg], type });
    if (!!msg.pushName) {
        let jid = msg.key.fromMe ? authState.creds.me.id : msg.key.participant || msg.key.remoteJid;
        jid = jidNormalizedUser(jid);
        if (!msg.key.fromMe) {
            ev.emit('contacts.update', [{ id: jid, notify: msg.pushName, verifiedName: msg.verifiedBizName }]);
        }
        // update our pushname too
        if (msg.key.fromMe && msg.pushName && authState.creds.me?.name !== msg.pushName) {
            ev.emit('creds.update', { me: { ...authState.creds.me, name: msg.pushName } });
        }
    }
    const historyMsg = getHistoryMsg(msg.message);
    const shouldProcessHistoryMsg = historyMsg
        ? shouldSyncHistoryMessage(historyMsg) && PROCESSABLE_HISTORY_TYPES.includes(historyMsg.syncType)
        : false;
    // State machine: decide on sync and flush
    if (historyMsg && syncState === SyncState.AwaitingInitialSync) {
        if (awaitingSyncTimeout) {
            clearTimeout(awaitingSyncTimeout);
            awaitingSyncTimeout = undefined;
        }
        if (shouldProcessHistoryMsg) {
            syncState = SyncState.Syncing;
            logger.info('Transitioned to Syncing state');
            // Let doAppStateSync handle the final flush after it's done
        }
        else {
            syncState = SyncState.Online;
            logger.info('History sync skipped, transitioning to Online state and flushing buffer');
            ev.flush();
        }
    }
    const doAppStateSync = async () => {
        if (syncState === SyncState.Syncing) {
            logger.info('Doing app state sync');
            await resyncAppState(ALL_WA_PATCH_NAMES, true);
            // Sync is complete, go online and flush everything
            syncState = SyncState.Online;
            logger.info('App state sync complete, transitioning to Online state and flushing buffer');
            ev.flush();
            const accountSyncCounter = (authState.creds.accountSyncCounter || 0) + 1;
            ev.emit('creds.update', { accountSyncCounter });
        }
    };
    await Promise.all([
        (async () => {
            if (shouldProcessHistoryMsg) {
                await doAppStateSync();
            }
        })(),
        (config.optimusInitialBufferRecovery ? config.optimusInitialBufferRecovery.runMessage(msg, () => processMessage(msg, {
            shouldProcessHistoryMsg,
            placeholderResendCache,
            ev,
            creds: authState.creds,
            keyStore: authState.keys,
            logger,
            options: config.options
        })) : processMessage(msg, { shouldProcessHistoryMsg, placeholderResendCache, ev, creds: authState.creds, keyStore: authState.keys, logger, options: config.options }))
    ]);
    // If the app state key arrives and we are waiting to sync, trigger the sync now.
    if (msg.message?.protocolMessage?.appStateSyncKeyShare && syncState === SyncState.Syncing) {
        logger.info('App state sync key arrived, triggering app state sync');
        await doAppStateSync();
    }
});

blocks.sync:
ev.on('connection.update', ({ connection, receivedPendingNotifications }) => {
    if (connection === 'open') {
        config.optimusInitialBufferRecovery?.open();
        if (fireInitQueries) {
            executeInitQueries().catch(error => onUnexpectedError(error, 'init queries'));
        }
        sendPresenceUpdate(markOnlineOnConnect ? 'available' : 'unavailable').catch(error => onUnexpectedError(error, 'presence update requests'));
    }
    if (!receivedPendingNotifications || syncState !== SyncState.Connecting) {
        return;
    }
    syncState = SyncState.AwaitingInitialSync;
    logger.info('Connection is now AwaitingInitialSync, buffering events');
    ev.buffer();
    const willSyncHistory = shouldSyncHistoryMessage(proto.Message.HistorySyncNotification.fromObject({
        syncType: proto.HistorySync.HistorySyncType.RECENT
    }));
    if (!willSyncHistory) {
        logger.info('History sync is disabled by config, not waiting for notification. Transitioning to Online.');
        syncState = SyncState.Online;
        setTimeout(() => ev.flush(), 0);
        return;
    }
    logger.info('History sync is enabled, awaiting notification with a 20s timeout.');
    if (awaitingSyncTimeout) {
        clearTimeout(awaitingSyncTimeout);
    }
    awaitingSyncTimeout = setTimeout(() => {
        if (syncState === SyncState.AwaitingInitialSync) {
            logger.warn('Timeout in AwaitingInitialSync, forcing state to Online and flushing buffer');
            syncState = SyncState.Online;
            ev.flush();
        }
    }, 20000);
});

blocks.processNode:
const processNode = (type, node, identifier, exec) => {
    const isOffline = config.optimusInitialBufferRecovery ? config.optimusInitialBufferRecovery.isOffline(node) : !!node.attrs.offline;
    if (isOffline) {
        offlineNodeProcessor.enqueue(type, node);
    }
    else {
        processNodeWithBuffer(node, identifier, exec);
    }
};

blocks.processNodeWithBuffer:
const processNodeWithBuffer = async (node, identifier, exec) => {
    ev.buffer();
    await execTask();
    ev.flush();
    function execTask() {
        return exec(node, false).catch(err => onUnexpectedError(err, identifier));
    }
};
const makeOfflineNodeProcessor = () => {
    const nodeProcessorMap = new Map([
        ['message', handleMessage],
        ['call', handleCall],
        ['receipt', handleReceipt],
        ['notification', handleNotification]
    ]);
    const nodes = [];
    let isProcessing = false;
    const enqueue = (type, node) => {
        nodes.push({ type, node });
        if (isProcessing) {
            return;
        }
        isProcessing = true;
        const promise = async () => {
            while (nodes.length && ws.isOpen) {
                const { type, node } = nodes.shift();
                const nodeProcessor = nodeProcessorMap.get(type);
                if (!nodeProcessor) {
                    onUnexpectedError(new Error(`unknown offline node type: ${type}`), 'processing offline node');
                    continue;
                }
                await nodeProcessor(node);
            }
            isProcessing = false;
        };
        promise().catch(error => onUnexpectedError(error, 'processing offline nodes'));
    };
    return { enqueue };
};
